def is_visible(v, me):
    # Rule 1: the version was created by me, or by a txn that committed before I started.
    if not (v.begin_ts == me.ts or committed_before(v.begin_ts, me)):
        return False
    # Rule 2: nobody whose writes I can see has replaced it yet.
    if v.end_ts == INF:
        return True
    return not (v.end_ts == me.ts or committed_before(v.end_ts, me))
